exec((__import__('pathlib').Path(__file__).parent/'gaosi_a.py').read_text(encoding='utf-8').split("B('01出术'")[0])
B('23太阳神',[
C('bao_shouwang','包守望','包守望继承巨额家产，却把兴趣几乎全放在生物与标本上。他从小在花园寻找昆虫，长大后让宅邸堆满柜架、箱子和各类收藏，连访客走到书桌前都得小心绕行。他请高斯对昆虫复眼作显微解剖摄影，关心的是能看清哪些结构，对周围人眼中的豪宅气派与财产经营反而没有耐心。父亲去世后，他为免麻烦把经营中的事业低价出让，让账房管钱，给依附者留下巧立名目和偷取财物的空间；宽厚并不意味着他完全无法拒绝，马凤莉企图用亲密关系取得控制时，他把她推开。遗嘱把财产用于生物标本博物馆和学生奖学金，又特别保障老仆阿根终身留职，显示他对研究和长期照料者有自己的安排。最终马凤莉向他注入毒液，他在失去说话能力的短暂时间里紧握命名为太阳神的蝎子，留下指向凶手名字的线索。终局他已死亡，财富按遗嘱转入公共事业，不能成为复登场时无限提款的随身能力。他的专注、善意和疏于财务互相纠缠，遇陌生世界会先问生物如何生活，却不自动掌握所有物种或毒药的实战用法。','被马凤莉用毒液杀死，遗嘱将财产用于博物馆并保障阿根工作。','富有的生物收藏者，生活空间被标本和箱柜占满；稳定衣饰未详。','研究和保存生物，把财富用于自己的兴趣及其延续。','通常回避财务麻烦，遭致命袭击时仍试图留下具体线索。','生物收藏与研究兴趣、委托专业摄影和遗产安排；非超常毒物专家。',[(68,133,'摄影委托及蝎子命名'),(509,568,'一生兴趣、财务与遗嘱'),(893,929,'临终线索及凶手')],[('出现陌生生物或观察难题','有专业工具和协作者可用','先安排研究和记录，忽略场面礼节。'),('别人要求自己管琐碎账目','认为钱足够且怕麻烦','容易授权旁人，留下被利用空间。'),('遭到危险且说话受限','仍有短暂动作能力','尝试借已知物件留下信息，不获得必然被读懂的密码。')],roles=['单书主角'],revive=True,uncertainties=['结尾水果别名有重复异文，按整体情节保留太阳神与凤莉姓名的谐音线索，不视作生物能力。']),
C('ma_fengli','马凤莉','马凤莉是马立德的侄女，离婚后住入包家，漂亮而习惯自己能吸引男性注意。叔父希望她嫁给包守望，以便更自由地使用这家财产，她本人也曾主动接近，却被只关心生物的包守望拒绝。这种拒绝在她心中变成难以忍受的羞辱，最终导致她取用宅中毒液向包守望脸部注射，造成死亡。案件初查时，众人都在争论遗产和钱，她强调自己住在这里并没得过好处，阿根揭出婚姻算计，她便掴打老人，既愤怒又快要哭出来。毒液线索一度把曾偷卖毒液的陈中推到前面，但化验和临终蝎子暗示又把调查带回她身上。李玉芳说案件结束时，她失控喊出包守望从来不看自己、自己要他死的话，随后被铐走。终局她不是具有特殊魅惑能力的妖女，也没有证据表明她能合成或远程操纵毒物；杀伤依赖宅中现成收藏与近身注射机会。演绎可保留她把自我价值系于被关注、在羞辱面前反应过激的逻辑，却不能将每次拒绝都机械触发杀人，更不能把她对男性应当动心的期待当作世界必须遵守的规则。','被李玉芳识破，情绪爆发承认杀意后被捕。','三十二岁，艳丽的离婚女子；失控时脸色发白、双手握紧。','原想取得关系与财产位置，最终因被拒绝而报复。','否认获利，受到揭露时打人，关键指认下失控。','社交接近、利用现成毒液实施近身袭击；无配毒和超常魅惑证据。',[(437,452,'身份与依附关系'),(688,724,'拒绝、打人和毒死事实'),(893,929,'线索与被捕')],[('自认应受关注','对方持续把兴趣放在别处','会把忽视解读为羞辱，试图强求回应。'),('旁人揭出私下算计','当众体面受损','可能以斥骂或掌掴压住话题。'),('明确证据逼近自身','先前辩词已失效','会暴露积累的怨恨，难维持冷静表演。')],roles=['反派'],scores={'physical':1,'energy':0,'scope':1,'sustain':1,'range':0,'combat':1},tier='纸',limits='毒液是特定收藏物，须实际取得并近身使用；不复制原文毒量为现实剂量，不推导无限剧毒能力。'),
C('ma_lide','马立德','马立德是包守望父亲第三位妾侍的弟弟，借舅老爷身份长期住在包家，上一代去世后更俨然以主人自居。他不直接管理研究，却掌握亲缘和介绍人进宅的便利，把侄女马凤莉安置进来，希望通过婚姻扩大对财产的支配，也介绍养狗人工作。家中账目给他大量开支，他巧立名目从宽松管理中获利，遇到高斯因账房扣回佣而发怒，便用小不忍乱大谋提醒同伴收敛，真正担心的不是公正，而是逼得包守望认真追究会影响长久利益。包守望死亡后，他原以为还可决定下人去留，怒令把阿根打发走，却得知账户冻结、遗嘱保护老仆，自己未来的依靠也动摇。面对警方追问，他承认不能做得太过分，仍想把死亡解释为蝎子事故，并替侄女的尴尬行为解围。终局确定凶手是马凤莉，不能把马立德的经济寄生自动改写成谋杀共犯。他的阶段性对立来自仗亲缘摆权威、贪图稳定利益和压制证人，这些都依赖宅内关系；离开这个体系，舅老爷的称呼不会给他普遍命令权。','财源因遗产安排改变，侄女被捕；未证实参与谋杀。','五十四岁，摆舅老爷气派；愤怒时发号施令。','维持包家供养并扩大自己和亲属对钱财的控制。','尽量避免把贪取做得太显眼，地位受损时急于驱赶揭短者。','亲缘身份、家内人事关系和账目获利；不等同法律所有权。',[(437,450,'关系与人事'),(533,544,'巧立开支'),(638,724,'驱仆、解释大谋和为侄女解围')],[('有人威胁公开财务问题','现有供养仍可持续','劝同伙暂忍，避免惹主人认真追究。'),('依赖的权威突然消失','仍试图维持旧秩序','继续命令下人，直到现实规则反驳他。'),('亲属丑事被公开','可能影响自身地位','淡化为私人问题，阻止继续追问。')],roles=['阶段性对立者']),
C('zhu_jin','朱金','朱金在包守望父亲生前就任账房，因长期信任掌管全家财务，也因此最熟悉如何把主人的宽松和怕麻烦变成自己的便利。高斯拿着主人签署的摄影委托来支款，他正与其他寄居者赌牌，先催收条，再只开出应付数额的八成，把两成回扣说成惯例。他并不表现出这是一项必须征得主人同意的特别要求，而是以办事人的位置压低来客，遭高斯强硬拒绝后才愤然重开支票，仍用抛掷和辱骂维持面子。包守望死亡后，朱金想继续按旧模式处理争执，却因账户被冻结无法付款，这才显示账房权限终究不等于财产所有权。警方问回扣和大谋时，他紧张不安，后来陈中被查出偷卖毒液，他又愤怒斥责对方害了大家，忽略自己同样参与侵蚀主人财产的事实。终局女凶手被捕，并没有证据将朱金列为杀人共谋。可调用的对立性是扣款、账目与流程控制，以及对低地位者傲慢、对直接追责者退缩的差异；他没有无限资金，也不能越过账户冻结或正式遗嘱继续发钱。','谋杀嫌疑未成立；遗产账户冻结，原有账房支配条件改变。','五十四岁账房，衣饰华丽，戴钻戒与白金表，赌牌时大声叫骂。','从代理财务的权力中持续取得利益并维持体面。','面对普通领款者强硬，遇正面追责则恼怒而退让。','账目办理、支票与付款流程控制；受真实授权和账户状态限制。',[(165,212,'扣回佣与争执'),(443,447,'任职背景'),(638,687,'冻结与追问'),(827,832,'责骂陈中')],[('别人必须经自己领款','认为对方会接受行业借口','把私取说成惯例。'),('对方准备直接找主人','越过自己控制的流程','可能退让但以态度挽回面子。'),('同类行为被别人揭穿','自身利益也受威胁','倾向责怪闯祸者，掩饰共同问题。')],roles=['阶段性对立者']),
C('chen_zhong','陈中（太阳神）','陈中是包守望的远房表亲，名义上在家中帮手，实际也依靠主人的财富生活。他衣饰讲究，知道亲戚收藏大量毒蛇毒液后，又偶然听研究所说某些品种很值钱，便以少取一点主人不会察觉为理由，几次偷拿出去出售。这个偷窃不是谋杀，却使他在包守望被毒死后成为最容易被怀疑的人。阿根尚未说出指控，仅望着他，他就紧张喊自己没有杀人，想跑又被高斯拦下，随后跪到李玉芳面前求信，主动交代偷卖经过。他明白包守望宽厚，甚至承认就算被当场抓住，对方可能仍会给钱，这使他的贪取更显出机会主义而不是绝境。警方暂以谋杀罪拘捕，他反复辩称只偷毒液，受朱金斥责时又爆发，说别人能偷更值钱的东西，自己才会退而求其次。真正的临终线索最终指向马凤莉，他被命令放开，洗脱杀人嫌疑，偷窃本身却没有因此成为无事。终局陈中对毒液的了解主要是售价和存放处，没有证实专业毒理或武器训练；害怕被捕也不是承认所有指控，角色应允许承认自己的罪责并坚持否认未犯之事。','被错误以谋杀拘捕，真凶查明后获释于该嫌疑；偷卖行为已公开，另案结果未写。','二十九岁，油头粉面，重装饰；受压会发抖、哭泣或跪求。','靠亲缘获得生活条件，再偷取高价收藏牟利。','心虚使其过早自辩，却始终否认未实施的谋杀。','接触收藏与转卖渠道；没有可靠配毒、射击或战斗能力。',[(452,453,'身份'),(730,796,'偷卖、自辩与拘捕'),(827,832,'利益对比'),(912,929,'释放与真正凶手')],[('发现主人不细查的贵重物','外部买家给出高价','容易用少量不会被发现来合理化偷取。'),('调查触到自己真实违法处','又涉及更严重案件','急于撇清大罪，同时承认局部事实。'),('同样获利者指责自己','感到责任被单方面推来','会反击揭出别人的行为。')],roles=['阶段性对立者']),
C('a_gen','阿根（太阳神）','阿根是包家的老仆，长久看见包守望沉迷生物、疏于理财，也看见寄居亲属和管账人不断占便宜。他对主人敬爱，对其他人积怨很深，包守望一死便反复认定是谋财害命，要求警方听自己说。他掌握不少真正有用的生活细节：马立德与侄女的婚姻盘算、马凤莉遭拒的经历、陈中偷拿毒液，都来自在宅内长期走动与观察。然而他的忠诚也让判断过快，一见偷毒液事实便把陈中当凶手，甚至以愤怒辱骂代替证据。马凤莉打他耳光时，他不敢还手，却更决心把事情抖出；得到李玉芳允许后，话说得更响，成为调查中既重要又需要核验的证人。包守望遗嘱保障他在未来博物馆工作至死，不得解雇，这使马立德驱赶他的命令失效，但阿根原先并不知道这项安排。终局真凶落网，他的具体生活去向没有细写，长期工作保障已经明确。卡片不把老人写成能看穿所有人的神探，也不因他幸灾乐祸就推导杀主阴谋；演绎应让真实观察、阶层怨气与过早定论同时存在，在证据纠正后能把指责收回。','真凶查出，遗嘱确认他在博物馆终身任职不得解雇。','老仆人，言语激动，挨打后捂脸而继续控诉。','为敬爱的主人讨公道，揭露长期侵蚀家产的人。','越受压制越想揭短，但容易把确实偷窃扩大成谋杀结论。','长期生活观察、具体证言和熟悉收藏位置；无全知判断。',[(564,568,'终身工作保障'),(638,710,'受压与揭露'),(730,786,'毒液线索与武断'),(848,854,'原不知遗嘱、敬爱主人')],[('熟悉的弱势主人受害','长期已有对他人的不满','立即怀疑惯常占便宜者，需要逐项核验。'),('被权势者要求闭嘴','仍有愿听证言的调查者','把积存的具体见闻说出来。'),('自己提供的线索只证明较小过错','调查得出不同结论','应区分亲眼看见与愤怒推测，不坚持无据定罪。')],roles=['单书主角'])],excluded=[{'name':'朱振香、黄应方、汪律师','reason':'前两人依附或工作关系不自动证明独立犯罪；律师放任财务弊病但仅作一次性信息提供者，无主角或跨书线。'},{'name':'太阳神蝎子','reason':'被用作临终线索的生物，无拟人意志，且非真正致死来源，不单列反派。'}],notes=['结尾“波萝/菠萝”存在明显同义重复异文，推理链不擅改原文；毒蛇名称与毒理仅按小说情节，不当现实生物学资料。'])
B('24晚礼服',[
C('yan_ling','燕玲','燕玲是生活优雅的服装设计师，与高斯相识后关系迅速亲近，平日的作品和审美让他十分信任。她从小在贵族式寄宿学校长大，一直以为父亲是四处旅行的人，直到近来才知道父亲属于犯罪组织且失踪被警方寻找。穆尔西斯利用她担心父亲身份曝光的心理，逼她设计一件镶满水钻的晚礼服，将失窃真钻混在其中，再借东京服装比赛、杂志宣传和模特公开穿着过关。她的反常设计与苍白神情引起高斯疑惑，卧底模特李玉芳又掌握了与男爵的会面录音，因而一度认定她主动参与走私。另一伙歹徒绑架并搜毁住宅后把她放回，进一步加深她对报警后能否长期受保护的恐惧。高斯带伤赶来，她终于说出受威胁原因，听明白父亲的罪责不等于自己的责任，选择交出晚礼服；电话被切断时，她与高斯装箱准备出门，外面警方已与来袭者交火。终局钻石交给李玉芳，她脱离当次胁迫，却没有得到父亲下落或永久安全的结论。角色保留专业设计与害怕连累家人的脆弱，也能在得到具体支持时改变决定，不把受胁迫的执行写成天生犯罪忠诚。','向高斯说明胁迫并交出藏钻晚礼服，警方接收赃物；父亲下落未解。','优雅的年轻设计师，危机中脸色苍白、失神落泪。','保住父亲与自己的生活，最终避免自己继续犯罪。','恐惧时隐瞒，得到可信支持后承认事实并合作。','服装设计与材料安排；藏钻方案受犯罪方要求，不是无条件走私技能。',[(306,350,'身份与警方观察'),(575,625,'父亲、胁迫、设计与转变'),(627,660,'交衣与脱险')],[('家人秘密被别人掌握','担心自己也受牵连','可能沉默服从，误把帮助犯罪当唯一选择。'),('作品突然背离自己的审美','暗中承担他人任务','情绪和作品会留下异常，不总能掩饰。'),('朋友说明责任边界并给出具体保护途径','仍有交出证物机会','愿意坦白并采取实际合作。')],roles=['主角','受胁迫的阶段性对立者']),
C('muersisi','穆尔西斯','穆尔西斯外号男爵，原是军中秘密工作组人员，后来成为欧洲著名珠宝贼并加入大走私组织，曾被判长期监禁又越狱。他以知道燕玲父亲犯罪背景为把柄，让设计师把失窃钻石混入晚礼服的水钻，通过公开时装宣传将最显眼的物品变成海关最不容易怀疑的载体。对高斯，他不满足于在远处威胁，而是突然现身追问警方说过什么；高斯想先发制人，却被他以腹部和后颈的连续攻击打倒，鞋底再弹出多排刀刃，逼近脸部作为谈判压力。高斯冒险折断其中一片刺入他小腿后脱身，奔跑中又遭消音枪射伤。后来男爵与同伙乘车靠近燕玲住所，打算会面或改变计划，却撞进警方埋伏，冲出车门后中枪倒地；文本没有明说死亡，不能补写战死或无伤逃脱。终局其犯罪身份和本次计划均已暴露。可保留训练、鞋刃与枪械的危险，却不能把军情履历变成无限技能库；装备依赖实物，近身优势也可能被自己暴露的刀片反制，组织规模不等于个人无敌。','在燕玲住所外围枪战中中枪倒地，具体生死未交代。','秃头、眼珠外凸而白多黑少；自称男爵，鞋藏弹出刀片。','完成盗钻转运并控制可能向警方泄露的人。','用近身重击和器械逼问，受反抗后动用枪械。','近身搏斗、鞋底刀片、消音手枪与胁迫安排；需具体装备。',[(388,422,'履历与走私目标'),(472,520,'搏斗、鞋刃与枪伤'),(587,625,'胁迫和方案'),(636,650,'中枪结局')],[('目标家人有可用秘密','目标误解其责任','将秘密变成要求执行任务的压力。'),('有人接触警方后仍可拦截','自己具近身或武装优势','迅速压倒并逼问其所知。'),('目标反击伤到自己','仍有枪械或同伴','升级追击，但不会免于真实伤害与埋伏。')],roles=['反派'],aliases=['莫尔西斯（异写）','男爵'],scores={'physical':2,'energy':0,'scope':1,'sustain':2,'range':2,'combat':4},tier='并',deployment='综合终局被识破的经历，以中枪前最后可行动形态作明确回溯式登场；不判定原文死亡，也不默认伤势自行痊愈。',adaptations=[{'change':'参战若需要完整行动能力，回溯至中枪前，并保留计划败露的记忆。','reason':'原文中枪后状态不明，避免编造复活或恢复。','power_impact':'只恢复原有普通身体与已持装备的条件性使用。'}]),
C('yanling_masked_gang','晚礼服案的五名面具歹徒','五名戴可怕面具的歹徒属于争夺钻石的另一行动方，与穆尔西斯控制燕玲的组织不能直接合并。他们事先藏一人在高斯车后座，等他离开燕玲住所后用枪抵住后颈，迫使转入荒草岔路的木屋，其余人已等在附近。问话并不给完整背景，只要求交出小姐给的东西，把自己错误判断当作高斯一定藏有钻石的事实。高斯突袭拉倒、推撞了两人，却被人数和背后箍颈压住，遭掌掴和重击昏迷。醒来时衣服、相机和鞋跟都被拆毁，车也不见，表明歹徒对小型藏物处进行过无差别搜查。燕玲后来同样遭绑架，家中被翻得一片狼藉，晚礼服却被当普通衣物丢在地上，真正目标就在眼前而没有认出。她获释，警方推测与对方忌惮大组织有关，不能当成已经核实的个人善意。终局五人的姓名、最终逮捕情况没有交代。卡片保留武装伏击、人数协作与粗暴搜物，限制在实际准备的场地和人手；他们会因错误情报扩大暴力，也会错过最显眼的藏匿方式。','高斯与燕玲均脱离拘禁，钻石交警方；该伙具体成员结局未写。','五名男子戴黑红混杂的怪面具，真实面貌未公开。','从燕玲或其亲近者处夺取钻石。','先认定对方持物，再以殴打和拆毁搜查强求答案。','藏车伏击、持枪、多人近身控制和拆查物品；无神秘面具能力。',[(85,174,'伏击、人数、殴打与搜查'),(265,275,'宅内搜毁'),(431,442,'不同犯罪方判断'),(604,619,'绑架回述及真藏物法')],[('目标与持物者关系亲近','情报未充分核实','可能直接把目标当作转交节点。'),('对方否认拥有物品','己方人数和武器占优','用殴打和拆物试图取代核验。'),('复杂场景里有极显眼物件','注意集中于暗格鞋跟等位置','可能漏看公开伪装，不能自动发现赃物。')],roles=['反派'],scores=GUN,tier='并',uncertainties=['释放燕玲的具体原因只由警方推测，不能当作团伙已交代的动机。'])],excluded=[{'name':'燕玲的父亲','reason':'只通过女儿口述出现，失踪与犯罪背景没有独立行动场面；不虚构卡片姓名或能力。'},{'name':'男爵车上同伴','reason':'枪战中未具可区分身份，作为男爵的条件性组织支援记录。'}])
